#!/usr/bin/env bash
# Auto-generated by autombist -- compile and run the self-checking MBIST testbench
# for sram_sabtf_mbist with Icarus Verilog.
#
#   bash tb/run_tb.sh [<memory model .v> [more Verilog sources...]]
#
# With no arguments the generated behavioral model of the memory (sram_sabtf_model.v) is
# used. It is idealized: fault-free, no timing checks, contents power up unknown. To use
# the memory's own simulation model (module sram_sabtf), e.g. the Verilog model
# OpenRAM writes with the macro, pass it: everything on the command line is compiled
# instead of the generated model.
# Exit status: 0 on PASS; non-zero on FAIL, timeout or a compile error.
# Optional environment: IVERILOG, VVP, BUILD (default: a build/ directory next
# to this script), MBIST_MAX_CYCLES (the timeout, in clk cycles).
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
OUT="$(cd "$HERE/.." && pwd)"
if [ "$#" -eq 0 ]; then
    echo "note: no memory model given; using the generated behavioral model sram_sabtf_model.v" >&2
    set -- "$HERE/sram_sabtf_model.v"
fi
IVERILOG="${IVERILOG:-iverilog}"
VVP="${VVP:-vvp}"
BUILD="${BUILD:-$HERE/build}"
DEFINES=()
if [ -n "${MBIST_MAX_CYCLES:-}" ]; then
    DEFINES+=("-DMBIST_MAX_CYCLES=$MBIST_MAX_CYCLES")
fi

mkdir -p "$BUILD"
"$IVERILOG" -g2012 ${DEFINES[@]+"${DEFINES[@]}"} -s tb_sram_sabtf_mbist -o "$BUILD/tb_sram_sabtf_mbist.vvp" \
    "$HERE/tb_sram_sabtf_mbist.sv" \
    "$OUT/sram_sabtf_mbist.v" \
    "$OUT/march_c/march_c_algo.sv" \
    "$OUT/march_c/march_c_fsm.sv" \
    "$OUT/march_c/march_c_top.sv" \
    "$OUT/sram_sabtf_saboteur.v" \
    "$@"
cd "$BUILD"
"$VVP" -n "tb_sram_sabtf_mbist.vvp"
